-- =====================================================================
-- 13 · Mi cuenta: nombre visible y foto de perfil
-- Cada persona puede poner un nombre visible y una foto de perfil. Solo cambia lo suyo:
-- el rol sigue siendo cosa del administrador.
-- Las fotos van a una carpeta pública nueva, «avatares», dentro de una subcarpeta con el id
-- de cada usuario. Nadie puede subir ni borrar fotos en la carpeta de otro.
-- Ejecútalo una vez en Supabase → SQL Editor. Se puede repetir sin romper nada.
-- =====================================================================

alter table public.perfiles add column if not exists nombre text not null default ''
  check (char_length(nombre) <= 40);
alter table public.perfiles add column if not exists avatar text not null default ''
  check (char_length(avatar) <= 500);

-- Cambia el nombre visible y la foto del usuario que ha entrado (nunca el rol ni el correo).
create or replace function public.actualizar_mi_perfil(p_nombre text, p_avatar text) returns void
language plpgsql security definer set search_path = public as $$
declare
  base text := '/storage/v1/object/public/avatares/' || auth.uid()::text || '/';
begin
  if auth.uid() is null then
    raise exception 'Hay que entrar con una cuenta';
  end if;
  p_nombre := btrim(coalesce(p_nombre, ''));
  p_avatar := coalesce(p_avatar, '');
  if char_length(p_nombre) > 40 then
    raise exception 'El nombre puede tener como mucho 40 caracteres';
  end if;
  -- La foto solo puede ser una de la propia carpeta del usuario, o ninguna.
  if p_avatar <> '' and (position(base in p_avatar) = 0 or p_avatar !~ '^https://') then
    raise exception 'La foto no es válida';
  end if;
  update public.perfiles set nombre = p_nombre, avatar = p_avatar where id = auth.uid();
end $$;
revoke all on function public.actualizar_mi_perfil(text, text) from public, anon;
grant execute on function public.actualizar_mi_perfil(text, text) to authenticated;
grant select (nombre, avatar) on public.perfiles to authenticated;

-- Carpeta pública de fotos de perfil (máximo 2 MB, solo imágenes).
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatares', 'avatares', true, 2097152, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set public = true, file_size_limit = 2097152,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp'];

drop policy if exists "avatares: subir la propia" on storage.objects;
create policy "avatares: subir la propia" on storage.objects for insert to authenticated
  with check (bucket_id = 'avatares' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "avatares: ver la propia" on storage.objects;
create policy "avatares: ver la propia" on storage.objects for select to authenticated
  using (bucket_id = 'avatares' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "avatares: cambiar la propia" on storage.objects;
create policy "avatares: cambiar la propia" on storage.objects for update to authenticated
  using (bucket_id = 'avatares' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "avatares: borrar la propia" on storage.objects;
create policy "avatares: borrar la propia" on storage.objects for delete to authenticated
  using (bucket_id = 'avatares' and (storage.foldername(name))[1] = auth.uid()::text);


-- =====================================================================
-- 14 · Fotos de perfil en las reseñas
-- Devuelve la foto de perfil de quienes han escrito alguna reseña, para enseñarla junto a su
-- firma. No expone nada más del perfil (ni correo ni rol). Necesita el 13 ejecutado antes.
-- Ejecútalo una vez en Supabase → SQL Editor. Se puede repetir sin romper nada.
-- =====================================================================
create or replace function public.fotos_resenas() returns table (autor uuid, avatar text)
language sql stable security definer set search_path = public as $$
  select p.id, p.avatar
  from public.perfiles p
  where p.avatar <> '' and exists (select 1 from public.opiniones o where o.autor = p.id);
$$;
revoke all on function public.fotos_resenas() from public;
grant execute on function public.fotos_resenas() to anon, authenticated;


-- =====================================================================
-- 15 · Mi bodega: cantidad en gramos
-- Al marcar «Lo tengo» se puede apuntar cuántos gramos se tienen. Es opcional:
-- si no se pone nada, el campo queda vacío (no 0).
-- Ejecútalo una vez en Supabase → SQL Editor, después del 10. Se puede repetir sin romper nada.
-- =====================================================================
alter table public.bodega add column if not exists gramos integer;
alter table public.bodega drop constraint if exists bodega_gramos_validos;
alter table public.bodega add constraint bodega_gramos_validos
  check (gramos is null or (gramos between 1 and 100000 and tengo));


-- =====================================================================
-- 16 · Distintivo de España
-- Nueva columna «en_espana»: en la ficha aparece un circulito con los colores de la bandera y
-- una E. Se puede marcar o quitar desde «Editar ficha» (y los editores pueden proponerlo).
-- Fuente: lista oficial de precios de picadura de pipa del Comisionado para el Mercado de Tabacos,
-- Península y Baleares, 1 de octubre de 2026 (última resolución: 26-09-2026).
-- Solo se marcan las coincidencias seguras (154 fichas). Ver marcas/en_espana.md.
-- Ejecútalo una vez en Supabase → SQL Editor. Se puede repetir sin romper nada.
-- =====================================================================
alter table public.tabacos add column if not exists en_espana boolean not null default false;

-- Las propuestas de los editores también pueden traer «se vende en España».
create or replace function public.aprobar_propuesta(p_id bigint) returns text
language plpgsql security definer set search_path = public as $$
declare
  p public.propuestas;
  d jsonb;
  res text;
begin
  if not public.es_admin() then
    raise exception 'Solo el administrador puede aprobar propuestas';
  end if;
  select * into p from public.propuestas where id = p_id for update;
  if not found or p.estado <> 'pendiente' then
    raise exception 'La propuesta no existe o ya está revisada';
  end if;
  d := p.datos;
  if p.tipo = 'nueva' then
    insert into public.tabacos (nombre, marca, pais, tipo, hojas, corte, formato, descripcion, fuerza, notas, foto, en_espana)
    values (
      coalesce(d->>'nombre', ''), coalesce(d->>'marca', ''), coalesce(d->>'pais', ''),
      coalesce(d->>'tipo', ''),
      coalesce(array(select jsonb_array_elements_text(d->'hojas')), '{}'),
      coalesce(d->>'corte', ''), coalesce(d->>'formato', ''),
      coalesce(d->>'descripcion', ''), coalesce((d->>'fuerza')::int, 0),
      coalesce(array(select jsonb_array_elements_text(d->'notas')), '{}'),
      coalesce(d->>'foto', ''),
      coalesce((d->>'en_espana')::boolean, false)
    ) returning id into res;
  elsif p.tipo = 'cambio' then
    update public.tabacos set
      nombre      = coalesce(d->>'nombre', nombre),
      marca       = coalesce(d->>'marca', marca),
      pais        = coalesce(d->>'pais', pais),
      tipo        = coalesce(d->>'tipo', tipo),
      hojas       = case when d ? 'hojas' then array(select jsonb_array_elements_text(d->'hojas')) else hojas end,
      corte       = coalesce(d->>'corte', corte),
      formato     = coalesce(d->>'formato', formato),
      descripcion = coalesce(d->>'descripcion', descripcion),
      fuerza      = coalesce((d->>'fuerza')::int, fuerza),
      notas       = case when d ? 'notas' then array(select jsonb_array_elements_text(d->'notas')) else notas end,
      en_espana   = coalesce((d->>'en_espana')::boolean, en_espana)
    where id = p.tabaco_id;
    res := p.tabaco_id;
  else
    update public.tabacos set foto = coalesce(d->>'foto', foto) where id = p.tabaco_id;
    res := p.tabaco_id;
  end if;
  update public.propuestas set estado = 'aprobada', revisado_por = auth.uid(), revisado = now() where id = p_id;
  return res;
end $$;

