  ('391', 'Original Navy Cut', 'Original Navy Cut', 'Original Navy Cut es una mezcla de la familia Virginia de Capstan, prensado y cortado en láminas (flake). Lleva Virginia prensada y tratada al vapor. Es la lata azul. Marca de Mac Baren, hoy de Scandinavian Tobacco Group. En EE. UU. se vende como Capstan Flake Blue. Formato: lata de 50 g.', 'Original Navy Cut es una mezcla de la familia Virginia de Capstan, prensado y cortado en láminas (flake). Lleva Virginia prensada y tratada al vapor. Es la lata azul. Marca de Mac Baren, hoy de Scandinavian Tobacco Group. Formato: lata de 50 g.'),
  ('393', 'Gold Navy Cut', 'Gold Navy Cut', 'Gold Navy Cut es una mezcla de la familia Virginia de Capstan, prensado y cortado en láminas (flake). Es la lata dorada, más suave que la Original. Marca de Mac Baren, hoy de Scandinavian Tobacco Group. En EE. UU. se vendía como Capstan Flake Yellow. Formato: lata de 50 g.', 'Gold Navy Cut es una mezcla de la familia Virginia de Capstan, prensado y cortado en láminas (flake). Es la lata dorada, más suave que la Original. Marca de Mac Baren, hoy de Scandinavian Tobacco Group. Formato: lata de 50 g.'),
  ('395', 'Three Nuns', 'Three Nuns', 'Three Nuns es una mezcla de la familia Virginia de Three Nuns, en rodajas de cuerda (coins). Lleva Virginia, Kentucky curado al fuego y burley. Marca de Mac Baren. Se vende en lata de 50 g en Europa y de 1,75 oz en EE. UU. Formato: 50 g.', 'Three Nuns es una mezcla de la familia Virginia de Three Nuns, en rodajas de cuerda (coins). Lleva Virginia, Kentucky curado al fuego y burley. Marca de Mac Baren. Formato: lata de 50 g. Formato: 50 g.'),
  ('400', 'Full Aroma', 'Full', 'Full Aroma es una mezcla aromática de Amphora, cortado en tiras finas (ribbon). Lleva Virginia, Kentucky curado al fuego, orientales y cavendish negro. Marca de Mac Baren. En Alemania se vende como Amphora Full. Formatos: 50 g y 1,75 oz.', 'Full es una mezcla aromática de Amphora, cortado en tiras finas (ribbon). Lleva Virginia, Kentucky curado al fuego, orientales y cavendish negro. Marca de Mac Baren. Formatos: 50 g y 1,75 oz.'),
  ('408', 'Nº 2', 'Nº 2', 'Nº 2 es una mezcla aromática de Amphora. Lleva Virginia, burley y cavendish. Antes se llamaba Special Reserve No. 2. Marca de Mac Baren. Formato: 50 g.', 'Nº 2 es una mezcla aromática de Amphora. Lleva Virginia, burley y cavendish. Marca de Mac Baren. Formato: 50 g.'),
  ('409', 'Nº 8', 'Nº 8', 'Nº 8 es una mezcla aromática de Amphora. Lleva Virginia, burley y cavendish. Antes se llamaba Special Reserve No. 8. Marca de Mac Baren. Formato: 50 g.', 'Nº 8 es una mezcla aromática de Amphora. Lleva Virginia, burley y cavendish. Marca de Mac Baren. Formato: 50 g.'),
  ('411', 'Black and B.', 'Black and B.', 'Black and B. es una mezcla aromática de Holger Danske, desmenuzado y listo para cargar (ready rubbed). Lleva cavendish negro, burley y Virginia. Marca de Mac Baren. Antes se llamaba Black & Bourbon. Formatos: 40 g y 100 g.', 'Black and B. es una mezcla aromática de Holger Danske, desmenuzado y listo para cargar (ready rubbed). Lleva cavendish negro, burley y Virginia. Marca de Mac Baren. Formatos: 40 g y 100 g.'),
  ('423', 'Classic Amber Loose Cut', 'Classic Amber Loose Cut', 'Classic Amber Loose Cut es una mezcla aromática de Mac Baren. Antes se vendía como Vanilla Toffee Cream. Formatos: 50 g y 100 g.', 'Classic Amber Loose Cut es una mezcla aromática de Mac Baren. Formatos: 50 g y 100 g.'),
  ('424', 'Classic Flake', 'Classic Flake', 'Classic Flake es una mezcla aromática de Mac Baren, prensado y cortado en láminas (flake). Antes se vendía como Vanilla Cream Flake. Formato: 50 g.', 'Classic Flake es una mezcla aromática de Mac Baren, prensado y cortado en láminas (flake). Formato: 50 g.'),
  ('1103', 'Clan', 'Clan', 'La mezcla aromática clásica de Clan, cortada en tiras finas (ribbon). Lleva Virginia, burley, cavendish negro y perique, con un toque de frutos secos. La creó Theodorus Niemeyer y la elabora Scandinavian Tobacco Group. Antes figuraba aquí como Clan Original. Formato: 50 g.', 'La mezcla aromática clásica de Clan, cortada en tiras finas (ribbon). Lleva Virginia, burley, cavendish negro y perique, con un toque de frutos secos. La creó Theodorus Niemeyer y la elabora Scandinavian Tobacco Group. Formato: 50 g.'),
  ('1122', 'Sungold', 'Sungold', 'Sungold es una mezcla aromática de Stanwell, cortado en tiras finas (ribbon). Antes se llamaba Vanilla, nombre con el que aún se vende en EE. UU. Formato: 50 g.', 'Sungold es una mezcla aromática de Stanwell, cortado en tiras finas (ribbon). Formato: 50 g.'),
  ('1123', 'Navy Deluxe', 'Navy Deluxe', 'Navy Deluxe es una mezcla de la familia Virginia de Escudo, cortado en rodajas (coins). Lleva Virginia y perique. Se vende con la marca A&C Petersen, de Scandinavian Tobacco Group. Formato: 50 g.', 'Navy Deluxe es una mezcla de la familia Virginia de Escudo, cortado en rodajas (coins). Lleva Virginia y perique. Es de la marca A&C Petersen, de Scandinavian Tobacco Group. Formato: 50 g.'),
  ('1138', 'Original Danish Black V Mixture', 'Original Danish Black V Mixture', 'Original Danish Black V Mixture es una mezcla aromática de Planta, cortado en tiras finas (ribbon). Lleva Virginia y burley tratado como cavendish, con vainilla. Antes se llamaba Danish Black Vanilla. Formatos: bolsa de 40 g y lata de 50 g.', 'Original Danish Black V Mixture es una mezcla aromática de Planta, cortado en tiras finas (ribbon). Lleva Virginia y burley tratado como cavendish, con vainilla. Formatos: bolsa de 40 g y lata de 50 g.'),
  ('1142', 'Wild C', 'Wild C', 'Wild C es una mezcla aromática de Mc Lintock. Antes se llamaba Wild Cherry. Marca creada por Planta. Formato: 100 g.', 'Wild C es una mezcla aromática de Mc Lintock. Marca creada por Planta. Formato: 100 g.'),
  ('1143', 'R and M', 'R and M', 'R and M es una mezcla aromática de R and M, cortado en tiras finas (ribbon). Lleva Virginia y burley, con notas de ron y arce. Antes se llamaba Rum and Maple. Marca creada por Planta. Formato: 50 g.', 'R and M es una mezcla aromática de R and M, cortado en tiras finas (ribbon). Lleva Virginia y burley, con notas de ron y arce. Marca creada por Planta. Formato: 50 g.'),
  ('1164', 'Sweet Vanilla Honeydew', 'S.V.H.', 'Sweet Vanilla Honeydew es una mezcla aromática de Dan Tobacco, en láminas desmenuzadas (broken flake). En Alemania se vende ahora como S.V.H. Formatos: 50 g, 250 g y 500 g.', 'S.V.H. es una mezcla aromática de Dan Tobacco, en láminas desmenuzadas (broken flake). Formatos: 50 g, 250 g y 500 g.'),
  ('2044', 'Blue Label 369', 'Blau 369', 'Blue Label 369 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia, burley, perique y cavendish. Mezcla de Rüdiger Will. Aroma afrutado y de miel. Formatos: lata de 50 g y lata de 100 g.', 'Blau 369 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia, burley, perique y cavendish. Mezcla de Rüdiger Will. Aroma afrutado y de miel. Formatos: lata de 50 g y lata de 100 g.'),
  ('2046', 'Gold Label 779', 'Gold 779', 'Gold Label 779 es una mezcla de estilo inglés de Solani, cortado en tiras finas (ribbon). Lleva virginia, orientales y latakia. Mezcla de Rüdiger Will. También se vende como English Luxury. Formato: lata de 50 g.', 'Gold 779 es una mezcla de estilo inglés de Solani, cortado en tiras finas (ribbon). Lleva virginia, orientales y latakia. Mezcla de Rüdiger Will. Formato: lata de 50 g.'),
  ('2047', 'Green Label 127', 'Grün 127', 'Green Label 127 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia y cavendish. Mezcla de Rüdiger Will. Un toque de manzana. Formatos: lata de 50 g y lata de 100 g.', 'Grün 127 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia y cavendish. Mezcla de Rüdiger Will. Un toque de manzana. Formatos: lata de 50 g y lata de 100 g.'),
  ('2048', 'Red Label 131', 'Rot 131', 'Red Label 131 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia, burley y cavendish. Mezcla de Rüdiger Will. Esencias tropicales y un toque de whisky de malta. Formatos: lata de 50 g y lata de 100 g.', 'Rot 131 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia, burley y cavendish. Mezcla de Rüdiger Will. Esencias tropicales y un toque de whisky de malta. Formatos: lata de 50 g y lata de 100 g.'),
  ('2051', 'White and Black 763', 'White & Black 763', 'White and Black 763 es una mezcla de estilo inglés de Solani, cortado en tiras finas (ribbon). Lleva virginia, latakia y cavendish. Mezcla de Rüdiger Will. Formatos: lata de 50 g y lata de 100 g.', 'White & Black 763 es una mezcla de estilo inglés de Solani, cortado en tiras finas (ribbon). Lleva virginia, latakia y cavendish. Mezcla de Rüdiger Will. Formatos: lata de 50 g y lata de 100 g.'),
  ('2052', 'X - Sweet Mystery 113', 'X-Mystery 113', 'X - Sweet Mystery 113 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia y cavendish. Mezcla de Rüdiger Will. Formatos: lata de 50 g y lata de 100 g.', 'X-Mystery 113 es una mezcla aromática de Solani, cortado en tiras finas (ribbon). Lleva virginia y cavendish. Mezcla de Rüdiger Will. Formatos: lata de 50 g y lata de 100 g.'),
  ('2066', 'Cedros', 'Cedros', 'Cedros es una mezcla aromática de Ilsted, cortado en tiras finas (ribbon). Lleva virginia, burley, kentucky y cavendish. Marca del pipero danés Poul Ilsted. Aroma de frutos secos; se vende en caja de cedro. Formato: lata de 50 g.', 'Cedros es una mezcla aromática de Ilsted, cortado en tiras finas (ribbon). Lleva virginia, burley, kentucky y cavendish. Marca del pipero danés Poul Ilsted. Aroma de frutos secos; viene en caja de cedro. Formato: lata de 50 g.')
) as v(id, nombre_viejo, nombre_nuevo, desc_vieja, desc_nueva)
where t.id = v.id and t.nombre = v.nombre_viejo and t.descripcion = v.desc_vieja;


-- =====================================================================
-- 19 · Formatos en gramos
-- Se quitan las onzas (medida de EE. UU.): si la ficha ya tiene un formato en gramos, la onza
-- desaparece; si solo tenía onzas, se pasan a gramos (2 oz = 57 g, 8 oz = 227 g, 16 oz = 454 g,
-- 1,75 oz = 50 g, 1,5 oz = 42,5 g, 7 oz = 198 g, 14 oz = 397 g). 309 fichas.
-- Ejecútalo después del 18. Se puede repetir. No pisa fichas cambiadas a mano.
-- =====================================================================
update public.tabacos t
set formato = v.formato_nuevo,
    descripcion = case when t.descripcion = v.desc_vieja then v.desc_nueva else t.descripcion end
